213	pub(crate) fn build(name: &str, files: Vec<RawFile>, plan: &Plan, opts: &RustOptions) -> (Codebase, Vec<Diagnostic>) {
214	    let r = Resolver::new(&files, plan);
215	    let mut cb = Codebase::new(name);
216	    let mut diags = Vec::new();
217	
218	    for f in &files {
219	        if let Some(e) = &f.error {
220	            diags.push(Diagnostic { file: f.path.clone(), message: e.clone() });
221	        }
222	    }
223	
224	    // Modules and items first, so field types are resolved before flows.
225	    for f in &files {
226	        cb.add_file(SourceFile {
227	            path: f.path.clone(),
228	            language: "rust".into(),
229	            module: module_sym(&f.role.module),
230	            hash: f.hash.clone(),
231	            lines: f.text_lines,
232	        });
233	        for m in &f.modules {
234	            let id = module_sym(&m.path);
235	            let mut s =
236	                Symbol::new(id.clone(), m.path.last().cloned().unwrap_or_default(), SymbolKind::Module, f.path.clone());
237	            s.span = m.span;
238	            s.sig_hash = m.sig_hash;
239	            s.body_hash = m.body_hash;
240	            s.doc = m.doc.clone();
241	            s.visibility = m.vis.clone();
242	            s.tags = m.tags.clone();
243	            cb.add_symbol(s);
244	            for u in &m.uses {
245	                if u.alias == "*" {
246	                    if let Some(t) = r.resolve_internal(&id, &u.target, None) {
247	                        cb.add_relation(Relation::new(id.clone(), t, RelationKind::Imports, Confidence::Exact));
248	                    }
249	                    continue;
250	                }
251	                let (t, c) = r.resolve(&id, &u.target, None, Ns::Type);
252	                if keep_ref(&t) {
253	                    cb.add_relation(Relation::new(id.clone(), t, RelationKind::Imports, c));
254	                }
255	            }
256	        }
257	        for it in &f.items {
258	            let module = module_sym(&it.module);
259	            let id = ids::item_id(&module, it.kind, &it.name);
260	            let mut s = Symbol::new(id.clone(), &it.name, it.kind, f.path.clone());
261	            s.visibility = it.vis.clone();
262	            s.span = it.span;
263	            s.sig_hash = it.sig_hash;
264	            s.body_hash = it.body_hash;
265	            s.signature = it.signature.clone();
266	            s.doc = it.doc.clone();
267	            s.generics = it.generics.clone();
268	            s.tags = it.tags.clone();
269	            let scope = InScope::of(&it.type_params);
270	            s.members =
271	                it.members.iter().map(|m| r.member(&module, m, Some(&id), scope.with(&m.type_params))).collect();
272	            for m in &s.members {
273	                for t in &m.refs {
274	                    let c = if r.internal.contains(t) { Confidence::Exact } else { Confidence::External };
275	                    cb.add_relation(Relation::new(id.clone(), t.clone(), RelationKind::FieldType, c));
276	                }
277	            }
278	            for st in &it.supertraits {
279	                let (t, c) = r.resolve(&module, st, None, Ns::Type);
280	                if keep_ref(&t) {
281	                    cb.add_relation(Relation::new(id.clone(), t, RelationKind::Extends, c));
282	                }
283	            }
284	            r.add_uses(&mut cb, &id, &module, &it.sig_refs, Some(&id), scope);
285	            let ctx =
286	                FlowCtx { module: &module, self_ty: (it.kind == SymbolKind::Trait).then_some(&id), params: scope };
287	            if !it.flow.is_empty() {
288	                s.flow = r.flow(&ctx, &it.flow, opts);
289	            }
290	            for m in &it.methods {
291	                let mid = ids::method_id(&id, None, &m.name);
292	                let ms = r.method_symbol(&mid, &id, m, f, &ctx, opts, &mut cb);
293	                cb.add_symbol(ms);
294	            }
295	            cb.add_symbol(s);
296	        }
297	        for imp in &f.impls {
298	            let module = module_sym(&imp.module);
299	            let Some(self_segs) = &imp.self_ty else { continue };
300	            let (ty, _) = r.resolve(&module, self_segs, None, Ns::Type);
301	            if let Some((segs, _)) = &imp.trait_ {
302	                let (t, c) = r.resolve(&module, segs, Some(&ty), Ns::Type);
303	                if keep_ref(&t) || r.internal.contains(&t) {
304	                    cb.add_relation(Relation::new(ty.clone(), t, RelationKind::Implements, c));
305	                }
306	            }
307	            let ctx = FlowCtx { module: &module, self_ty: Some(&ty), params: InScope::of(&imp.type_params) };
308	            for m in &imp.methods {
309	                let mid = impl_method(&module, &ty, imp, &m.name);
310	                let mut ms = r.method_symbol(&mid, &ty, m, f, &ctx, opts, &mut cb);
311	                if let Some((_, disp)) = &imp.trait_ {
312	                    ms.tags.insert(0, format!("impl {disp}"));
313	                }
314	                cb.add_symbol(ms);
315	            }
316	        }
317	    }
318	
319	    aggregate_calls(&mut cb);
320	    (cb, diags)
321	}
