323	/// The id of the module at `segments` (crate name first), in the `cargo`
324	/// package named by the crate.
325	fn module_sym(segments: &[String]) -> SymbolId {
326	    let (krate, rest) = segments.split_first().map_or(("", &[][..]), |(k, r)| (k.as_str(), r));
327	    ids::module_id(&crate_package(krate), rest)
328	}
