334	/// The id of method `name` from impl block `imp` whose self type resolved
335	/// to `ty`.
336	fn impl_method(module: &SymbolId, ty: &SymbolId, imp: &RawImpl, name: &str) -> SymbolId {
337	    let self_ty = imp.self_ty.as_ref().map(|s| s.join("::")).unwrap_or_default();
338	    let trait_ = imp.trait_.as_ref().map(|(_, disp)| disp.as_str());
339	    ids::impl_method_id(module, ty, &self_ty, trait_, name)
340	}
