348	/// Keep a resolved reference as a relation target? Drops std and prelude.
349	fn keep_ref(id: &SymbolId) -> bool {
350	    let root = id.root();
351	    let first = root.as_deref().unwrap_or("?");
352	    !STD_ROOTS.contains(&first) && !PRELUDE.contains(&first)
353	}
