355	/// Which namespace a path's final segment is looked up in first. Rust keeps
356	/// types (and modules) apart from values (functions, constants), so a module
357	/// `config` and a function `config` in one module are both reachable.
358	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
359	enum Ns {
360	    Type,
361	    Value,
362	}
363	
364	/// The definitions one name has in one module, per namespace.
365	#[derive(Debug, Clone, Default)]
366	struct Slots {
367	    ty: Option<SymbolId>,
368	    value: Option<SymbolId>,
369	}
370	
371	impl Slots {
372	    fn insert(&mut self, kind: SymbolKind, id: SymbolId) {
373	        let slot = match kind {
374	            SymbolKind::Function | SymbolKind::Method | SymbolKind::Const | SymbolKind::Static => &mut self.value,
375	            SymbolKind::Macro => return,
376	            _ => &mut self.ty,
377	        };
378	        if slot.is_none() {
379	            *slot = Some(id);
380	        }
381	    }
382	
383	    fn get(&self, ns: Ns) -> Option<&SymbolId> {
384	        match ns {
385	            Ns::Type => self.ty.as_ref().or(self.value.as_ref()),
386	            Ns::Value => self.value.as_ref().or(self.ty.as_ref()),
387	        }
388	    }
389	}
