392	    module: &'a SymbolId,
393	    self_ty: Option<&'a SymbolId>,
394	    /// Generic parameters in scope: the item's own, or the impl's or
395	    /// trait's (a method's own are added by [`Resolver::method_symbol`]).
396	    params: InScope<'a>,
397	}
