399	/// The generic type and const parameters in scope at one point, as declared:
400	/// an item's own, or an impl's or trait's plus one method's. A path whose
401	/// first segment is one of them names a parameter, never a same-named item,
402	/// whatever its spelling (`T`, `V2`, `Store`).
403	///
404	/// Scope is always known: every path the resolver sees comes from an item,
405	/// impl or trait whose generics the collector recorded, and items nested in
406	/// function bodies are not collected, so there is no name-shape fallback.
407	#[derive(Debug, Clone, Copy, Default)]
408	struct InScope<'a> {
409	    enclosing: &'a [String],
410	    own: &'a [String],
411	}
412	
413	impl<'a> InScope<'a> {
414	    /// The parameters of a top-level item, impl or trait.
415	    fn of(own: &'a [String]) -> Self {
416	        InScope { enclosing: &[], own }
417	    }
418	
419	    /// This scope plus a member's own parameters (a method in an impl or
420	    /// trait). Generics nest one level deep: members never nest further.
421	    fn with(self, own: &'a [String]) -> Self {
422	        debug_assert!(self.enclosing.is_empty(), "generic scopes nest one level");
423	        InScope { enclosing: self.own, own }
424	    }
425	
426	    fn contains(&self, name: &str) -> bool {
427	        self.own.iter().chain(self.enclosing).any(|p| p == name)
428	    }
