 10	/// The whole analysed codebase: files, symbols and relations.
 11	///
 12	/// All collections are ordered, so serialising a `Codebase` (for example with
 13	/// `serde_json`) is deterministic. Query methods return iterators in key
 14	/// order.
 15	#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
 16	pub struct Codebase {
 17	    /// Schema version, see [`MODEL_SCHEMA_VERSION`](crate::MODEL_SCHEMA_VERSION).
 18	    pub schema_version: u32,
 19	    /// Human name of the codebase (workspace or package name).
 20	    pub name: String,
 21	    /// Files keyed by path.
 22	    pub files: BTreeMap<SourcePath, SourceFile>,
 23	    /// Symbols keyed by id.
 24	    pub symbols: BTreeMap<SymbolId, Symbol>,
 25	    /// All relations, ordered.
 26	    pub relations: BTreeSet<Relation>,
 27	}
