 33	    }
 34	
 35	    /// Read a model serialised as JSON, refusing any schema version other
 36	    /// than [`MODEL_SCHEMA_VERSION`](crate::MODEL_SCHEMA_VERSION).
 37	    ///
 38	    /// ```
 39	    /// use sealmap_model::{Codebase, ModelJsonError};
 40	    ///
 41	    /// let json = serde_json::to_string(&Codebase::new("demo")).unwrap();
 42	    /// assert_eq!(Codebase::from_json(&json).unwrap().name, "demo");
 43	    ///
 44	    /// let v1 = r#"{"schema":1,"name":"old","files":{},"symbols":{},"relations":[]}"#;
 45	    /// assert!(matches!(Codebase::from_json(v1), Err(ModelJsonError::Version { found: Some(1), .. })));
 46	    /// ```
 47	    pub fn from_json(text: &str) -> Result<Self, ModelJsonError> {
 48	        #[derive(Deserialize)]
 49	        struct Probe {
 50	            schema_version: Option<u32>,
 51	            schema: Option<u32>,
 52	        }
 53	        let probe: Probe = serde_json::from_str(text).map_err(ModelJsonError::Json)?;
 54	        let found = probe.schema_version.or(probe.schema);
 55	        if found != Some(crate::MODEL_SCHEMA_VERSION) {
 56	            return Err(ModelJsonError::Version { found, expected: crate::MODEL_SCHEMA_VERSION });
 57	        }
 58	        serde_json::from_str(text).map_err(ModelJsonError::Json)
 59	    }
