 66	    /// Add a symbol. If the id already exists the two are merged: the first
 67	    /// definition wins for scalar fields, list fields are concatenated, and
 68	    /// the fingerprints are folded with [`Fingerprint::merge`](crate::Fingerprint::merge)
 69	    /// so an edit to either definition shows. This handles e.g.
 70	    /// `#[cfg]`-gated duplicate definitions deterministically.
 71	    pub fn add_symbol(&mut self, symbol: Symbol) {
 72	        match self.symbols.get_mut(&symbol.id) {
 73	            Some(existing) => {
 74	                existing.sig_hash = existing.sig_hash.merge(symbol.sig_hash);
 75	                existing.body_hash = existing.body_hash.merge(symbol.body_hash);
 76	                existing.members.extend(symbol.members);
 77	                for tag in symbol.tags {
 78	                    if !existing.tags.contains(&tag) {
 79	                        existing.tags.push(tag);
 80	                    }
 81	                }
 82	            }
 83	            None => {
 84	                self.symbols.insert(symbol.id.clone(), symbol);
 85	            }
 86	        }
 87	    }
