126	    /// Relations whose source is `id`.
127	    ///
128	    /// `Relation` orders by `from` first, so this is a range scan
129	    /// (O(log n + k)), not a pass over every relation.
130	    pub fn relations_from<'a>(&'a self, id: &'a SymbolId) -> impl Iterator<Item = &'a Relation> {
131	        let lower = Relation::new(id.clone(), SymbolId::min_value(), RelationKind::Contains, crate::Confidence::Exact);
132	        self.relations.range(lower..).take_while(move |r| &r.from == id)
133	    }
134	
135	    /// Relations whose target is `id`.
136	    pub fn relations_to<'a>(&'a self, id: &'a SymbolId) -> impl Iterator<Item = &'a Relation> {
137	        self.relations.iter().filter(move |r| &r.to == id)
138	    }
139	
140	    /// Relations of one kind.
141	    pub fn relations_of_kind(&self, kind: RelationKind) -> impl Iterator<Item = &Relation> {
142	        self.relations.iter().filter(move |r| r.kind == kind)
143	    }
