145	    /// The innermost *type* that owns `id` (the type for a method), or the
146	    /// module for free items. This is the "participant" a symbol belongs to
147	    /// in a sequence diagram.
148	    ///
149	    /// For external ids the parent path is returned as-is.
150	    pub fn owner_of(&self, id: &SymbolId) -> Option<SymbolId> {
151	        match self.symbols.get(id) {
152	            Some(sym) if sym.kind == SymbolKind::Method || sym.kind == SymbolKind::Function => sym.parent.clone(),
153	            Some(sym) => Some(sym.id.clone()),
154	            None => id.parent(),
155	        }
156	    }
