 90	    /// Collect a module and everything in it. `syn_vis` is the declared
 91	    /// visibility of an inline `mod` (`None` for a file's root module).
 92	    /// Returns the module's (`sig_hash`, `body_hash`).
 93	    fn module(
 94	        &mut self,
 95	        path: Segs,
 96	        attrs: &[Attribute],
 97	        syn_vis: Option<&syn::Visibility>,
 98	        items: &[Item],
 99	        span: Span,
100	        vis: Visibility,
101	    ) -> (Fingerprint, Fingerprint) {
102	        let mut sig = Fingerprinter::sig();
103	        sig.section("mod");
104	        fingerprint::attrs(&mut sig, attrs);
105	        sig.section("vis");
106	        if let Some(v) = syn_vis {
107	            fingerprint::feed(&mut sig, v);
108	        }
109	        sig.section("name");
110	        sig.ident(path.last().map_or("", String::as_str));
111	        let mut uses = Vec::new();
112	        for item in items {
113	            if let Item::Use(u) = item {
114	                flatten_use(&u.tree, &mut Vec::new(), &mut uses);
115	            }
116	        }
117	        self.raw.modules.push(RawModule {
118	            path: path.clone(),
119	            span,
120	            doc: doc_of(attrs),
121	            vis,
122	            uses,
123	            tags: tags_of(attrs),
124	            sig_hash: sig.finish(),
125	            body_hash: Fingerprint::default(),
126	        });
127	        let at = self.raw.modules.len() - 1;
128	        let mut body = Fingerprinter::body();
129	        body.section("mod");
130	        // rustfmt reorders `use`, `extern crate` and `mod x;` declarations,
131	        // and their order carries no meaning, so they are folded sorted.
132	        let mut declarations = Vec::new();
133	        for item in items {
134	            match item {
135	                Item::Use(_) | Item::ExternCrate(_) | Item::Mod(syn::ItemMod { content: None, .. }) => {
136	                    if !self.skip(item_attrs(item)) {
137	                        let mut d = Fingerprinter::body();
138	                        fingerprint::feed_canonical(&mut d, item, Canon::visit_item_mut);
139	                        declarations.push(d.finish());
140	                    }
141	                }
142	                _ => self.item(&path, item, &mut body),
143	            }
144	        }
145	        declarations.sort();
146	        body.section("declarations");
147	        for d in declarations {
148	            body.fingerprint(d);
149	        }
150	        let hashes = (sig.finish(), body.finish());
151	        self.raw.modules[at].body_hash = hashes.1;
152	        hashes
153	    }
