156	    /// imports. Their scope is really the block; widening it to the module
157	    /// is the cheap approximation, and far better than not seeing them:
158	    /// `use crate::events::Metrics;` inside a handler would otherwise leave
159	    /// `Metrics` unresolved, and `use sha2::Sha256;` would leave `Sha256`
160	    /// looking like nothing in particular rather than a dependency type.
161	    fn local_uses(&mut self, module: &Segs, block: &Block) {
162	        struct Uses(Vec<RawUse>);
163	        impl<'ast> syn::visit::Visit<'ast> for Uses {
164	            fn visit_item_use(&mut self, u: &'ast syn::ItemUse) {
165	                flatten_use(&u.tree, &mut Vec::new(), &mut self.0);
166	            }
167	        }
168	        let mut found = Uses(Vec::new());
169	        syn::visit::Visit::visit_block(&mut found, block);
170	        if found.0.is_empty() {
171	            return;
172	        }
173	        if let Some(m) = self.raw.modules.iter_mut().rev().find(|m| m.path == *module) {
174	            m.uses.extend(found.0);
175	        }
176	    }
